use serde_json::json;
use workflow_model::{CreateWorkflowDefinition, SubmitWhen};
use workflow_model::builder::{
    InputTypeBuilder, WorkflowActionBuilder, WorkflowDefinitionBuilder, WorkflowDisplayBuilder, WorkflowInputBuilder,
    WorkflowNodeBuilder, WorkflowVisualBuilder,
};

/// A greeting page: type a name, press Wave, and the bot answers.
pub fn definition(wave_action: &str) -> CreateWorkflowDefinition {
    let page = WorkflowVisualBuilder::new("page")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-2xl font-bold").text("Hello, {name}!").build(),
                WorkflowDisplayBuilder::new("flex gap-2")
                    .form(
                        "wave",
                        vec![
                            WorkflowDisplayBuilder::new("flex-1")
                                .input(
                                    "name",
                                    WorkflowInputBuilder::new()
                                        .r#type(InputTypeBuilder::text(Some("Your name".into())))
                                        .build(),
                                )
                                .build(),
                            WorkflowDisplayBuilder::new("")
                                .submit(
                                    vec![WorkflowDisplayBuilder::new("").text("Wave").build()],
                                    None,
                                    "wave",
                                    "default",
                                    "default",
                                )
                                .build(),
                        ],
                        SubmitWhen::OnSubmit,
                    )
                    .build(),
                WorkflowDisplayBuilder::new("text-muted-foreground").text("{reply}").build(),
            ],
        )
        .build();

    WorkflowDefinitionBuilder::new("hello", "Hello")
        .response("name", json!("there"))
        .response("reply", json!(""))
        .add_action(WorkflowActionBuilder::new("wave").run_server_action().target(wave_action).build())
        .add_node("home", WorkflowNodeBuilder::new("Hello").visual(page).build())
        .build()
}

use serde_json::json;
use workflow_model::builder::{
    Cond, InputTypeBuilder, WorkflowActionBuilder, WorkflowDefinitionBuilder, WorkflowDisplayBuilder,
    WorkflowInputBuilder, WorkflowNodeBuilder, WorkflowVisualBuilder,
};
use workflow_model::{CreateWorkflowDefinition, SubmitWhen};

/// Guess a number the bot is thinking of. The secret stays on the bot: each
/// guess goes to a server action that answers higher, lower or correct, and a
/// correct answer moves the page to the win screen.
pub fn definition(check_action: &str) -> CreateWorkflowDefinition {
    let play = WorkflowVisualBuilder::new("play")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("Guess the number").build(),
                WorkflowDisplayBuilder::new("text-muted-foreground").text("{gn_message}").build(),
                WorkflowDisplayBuilder::new("flex gap-2")
                    .form(
                        "guess",
                        vec![
                            WorkflowDisplayBuilder::new("flex-1")
                                .input(
                                    "gn_guess",
                                    WorkflowInputBuilder::new()
                                        .r#type(InputTypeBuilder::number(Some(1), Some(100)))
                                        .required(true)
                                        .build(),
                                )
                                .build(),
                            WorkflowDisplayBuilder::new("")
                                .submit(
                                    vec![WorkflowDisplayBuilder::new("").text("Guess").build()],
                                    None,
                                    "guess",
                                    "default",
                                    "default",
                                )
                                .build(),
                        ],
                        SubmitWhen::OnSubmit,
                    )
                    .build(),
            ],
        )
        .build();
    let won = WorkflowVisualBuilder::new("won")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("You got it!").build(),
                WorkflowDisplayBuilder::new("text-muted-foreground").text("{gn_message}").build(),
            ],
        )
        .build();

    WorkflowDefinitionBuilder::new("guess", "Guess the number")
        .response("gn_message", json!("I'm thinking of a number from 1 to 100."))
        .response("gn_done", json!(false))
        .add_action(WorkflowActionBuilder::new("guess").run_server_action().target(check_action).build())
        .add_node("play", WorkflowNodeBuilder::new("Play").visual(play).build())
        .add_node(
            "won",
            WorkflowNodeBuilder::new("Won")
                .parent_id("play")
                .condition(Cond::response_equals("gn_done", json!(true)))
                .visual(won)
                .build(),
        )
        .build()
}

use serde_json::json;
use workflow_model::builder::{
    Cond, WorkflowActionBuilder, WorkflowDefinitionBuilder, WorkflowDisplayBuilder, WorkflowNodeBuilder,
    WorkflowVisualBuilder,
};
use workflow_model::transform::TransformOp;
use workflow_model::{CreateWorkflowDefinition, WorkflowDisplay};

fn button(label: &str, action: &str) -> WorkflowDisplay {
    WorkflowDisplayBuilder::new("")
        .button(vec![WorkflowDisplayBuilder::new("").text(label).build()], None, action, "default", "default")
        .build()
}

fn set_mood(action: &str, mood: &str) -> workflow_model::WorkflowAction {
    WorkflowActionBuilder::new(action)
        .transform_responses(vec![TransformOp::Set { path: "mood".into(), value: json!(mood) }], true)
        .build()
}

/// No bot needed: buttons change responses with transforms, and conditions
/// pick what to show.
pub fn definition() -> CreateWorkflowDefinition {
    let page = WorkflowVisualBuilder::new("page")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("How is your day?").build(),
                WorkflowDisplayBuilder::new("flex gap-2")
                    .div(vec![button("Good", "good"), button("Meh", "meh")])
                    .build(),
                WorkflowDisplayBuilder::new("")
                    .condition(
                        Cond::response_equals("mood", json!("good")),
                        vec![WorkflowDisplayBuilder::new("text-primary").text("Glad to hear it.").build()],
                    )
                    .build(),
                WorkflowDisplayBuilder::new("")
                    .condition(
                        Cond::response_equals("mood", json!("meh")),
                        vec![WorkflowDisplayBuilder::new("text-muted-foreground").text("Tomorrow is another one.").build()],
                    )
                    .build(),
            ],
        )
        .build();

    WorkflowDefinitionBuilder::new("mood", "Mood")
        .add_action(set_mood("good", "good"))
        .add_action(set_mood("meh", "meh"))
        .add_node("home", WorkflowNodeBuilder::new("Mood").visual(page).build())
        .build()
}

use workflow_model::{CreateWorkflowDefinition, SubmitWhen, WorkflowDisplay};
use workflow_model::builder::{
    InputTypeBuilder, WorkflowActionBuilder, WorkflowDefinitionBuilder, WorkflowDisplayBuilder, WorkflowInputBuilder,
    WorkflowNodeBuilder, WorkflowVisualBuilder,
};

fn button(label: &str, action: &str) -> WorkflowDisplay {
    WorkflowDisplayBuilder::new("")
        .button(vec![WorkflowDisplayBuilder::new("").text(label).build()], None, action, "default", "default")
        .build()
}

fn submit(label: &str, action: &str) -> WorkflowDisplay {
    WorkflowDisplayBuilder::new("")
        .submit(vec![WorkflowDisplayBuilder::new("").text(label).build()], None, action, "default", "default")
        .build()
}

/// Typed values only reach an action from inside a form.
fn form(action: &str, content: Vec<WorkflowDisplay>) -> WorkflowDisplay {
    WorkflowDisplayBuilder::new("flex flex-col gap-4").form(action, content, SubmitWhen::OnSubmit).build()
}

/// Three pages: Next and Back move between nodes, and Done completes the instance.
pub fn definition() -> CreateWorkflowDefinition {
    let first = WorkflowVisualBuilder::new("first")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("Step 1: who are you?").build(),
                form(
                    "next",
                    vec![
                        WorkflowDisplayBuilder::new("")
                            .input(
                                "name",
                                WorkflowInputBuilder::new()
                                    .r#type(InputTypeBuilder::text(Some("Name".into())))
                                    .required(true)
                                    .build(),
                            )
                            .build(),
                        submit("Next", "next"),
                    ],
                ),
            ],
        )
        .build();
    let second = WorkflowVisualBuilder::new("second")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("Step 2: pick a number, {name}").build(),
                form(
                    "next",
                    vec![
                        WorkflowDisplayBuilder::new("")
                            .input(
                                "favorite",
                                WorkflowInputBuilder::new().r#type(InputTypeBuilder::number(Some(1), Some(10))).build(),
                            )
                            .build(),
                        WorkflowDisplayBuilder::new("flex gap-2")
                            .div(vec![button("Back", "back"), submit("Next", "next")])
                            .build(),
                    ],
                ),
            ],
        )
        .build();
    let summary = WorkflowVisualBuilder::new("summary")
        .block(
            "mx-auto flex max-w-md flex-col gap-4 p-8",
            vec![
                WorkflowDisplayBuilder::new("text-xl font-semibold").text("Thanks, {name}").build(),
                WorkflowDisplayBuilder::new("text-muted-foreground").text("You picked {favorite}.").build(),
                WorkflowDisplayBuilder::new("flex gap-2")
                    .div(vec![button("Back", "back"), button("Done", "finish")])
                    .build(),
            ],
        )
        .build();

    WorkflowDefinitionBuilder::new("steps", "Steps")
        .add_action(WorkflowActionBuilder::new("next").next_node().build())
        .add_action(WorkflowActionBuilder::new("back").previous_node().build())
        .add_action(WorkflowActionBuilder::new("finish").submit().build())
        .add_node("a_start", WorkflowNodeBuilder::new("Step 1").visual(first).build())
        .add_node("b_details", WorkflowNodeBuilder::new("Step 2").parent_id("a_start").visual(second).build())
        .add_node("c_summary", WorkflowNodeBuilder::new("Summary").parent_id("b_details").visual(summary).build())
        .build()
}
